 for(let i=24;i<2000;i++)insert.run(policy.budgetId,'synthetic-paid-'+i,'{}',1,1,0,'{}',0);
 const state={policy,benchmarkIterationActivatedAtMs:1000,benchmarkIterationHistory:[{iterationId:policy.benchmarkIteration.iterationId,startedAtMs:1000,deadlineAtMs:7201000,sourceSha256:h}],startedAtMs:1000,deadlineAtMs:7201000,lastNow:1000,windows:[{startedAtMs:1000,deadlineAtMs:1801000}],admissions:[{key:policy.priorUnknowns[0].key,cost:100000000,uncertaintyVersion:1,type:'external',retryAtMs:1000}],dispatches:[{key:'synthetic-original:recovery-1',sourceKey:policy.priorUnknowns[0].key,baseKey:'synthetic-original',attempt:1}],halted:'EvaluationBudgetExceeded',cancelled:true,pacing:{},predecessorReservations:db.prepare('SELECT * FROM evaluation_reservations ORDER BY rowid').all(),predecessorBudget:db.prepare('SELECT * FROM evaluation_budgets').get(),contractHistory:[]};
 db.prepare('UPDATE evaluation_budgets SET '+column+'=?').run(JSON.stringify(state));
 const current=()=>db.prepare('SELECT '+column+' state FROM evaluation_budgets').get().state,beforeRows=db.prepare('SELECT * FROM evaluation_reservations ORDER BY rowid').all(),beforeBudget=db.prepare('SELECT * FROM evaluation_budgets').get();
 const approval={ownerAuthorized:true,benchmarkOnly:true,ownerAnswer,previousMaximumRequests:2000,maximumRequests:4000,previousMaximumInputTokens:8000000,maximumInputTokens:16000000,maximumOutputTokens:3000000,cumulativeCapNanodollars:8000000000,resetCounters:false,resetOriginalStart:false,retainAllUnknownReserves:true};
 const proposal=async({approvalChange={},proofChange={},closureChange={},newIteration=true}={})=>{
  const text=JSON.stringify({...approval,...approvalChange}),source=join(directory,'owner-quota-approval.json');await writeFile(source,text);
  const previousRuntimeSha256=sha(current()),next={...structuredClone(policy),source:'synthetic-next-code',requestExtension:{source,sourceSha256:sha(text),previousRuntimeSha256,previousMaximumRequests:2000,maximumRequests:4000},inputTokenExtension:{source,sourceSha256:sha(text),previousRuntimeSha256,previousMaximumInputTokens:8000000,maximumInputTokens:16000000}};
  if(newIteration){const timerText=JSON.stringify({...approval,ownerAnswer:'automatically reset it to 2 hours for each new benchmark run',durationMilliseconds:7200000}),timerSource=join(directory,'owner-timer-approval.json');await writeFile(timerSource,timerText);next.benchmarkIteration={source:timerSource,sourceSha256:sha(timerText),previousRuntimeSha256,previousDeadlineAtMs:state.deadlineAtMs,previousWindowCount:state.windows.length,iterationId:'synthetic-next-run',durationMilliseconds:7200000};}
  const closure=JSON.stringify({ownedPid:123,code:1,signal:null,stopping:true,stopReason:'IntegrationRuntimeHalted',cleanupConfirmed:true,monitorFailure:null,failure:null,finishedAt:new Date(2000).toISOString(),...closureChange}),closureSource=join(directory,'closed-supervisor.json');await writeFile(closureSource,closure);
  const proof=JSON.stringify({ownerAuthorized:true,benchmarkOnly:true,ownerAnswer,cumulativeCapNanodollars:8000000000,previousRuntimeSha256,closureSource,closureSha256:sha(closure),unknownReservations:[],resumeCancellation:true,resetCounters:false,resetOriginalStart:false,retainAllUnknownReserves:true,...proofChange}),proofSource=join(directory,'stopped-transport.json');await writeFile(proofSource,proof);
  return {next,review:{verdict:'PASS',BLOCKING:'NONE',codeSha256:next.codeSha256,modelsSha256:next.modelsSha256,gateSha256:h,stoppedTransport:{source:proofSource,sha256:sha(proof)}}};
 };
 const advance=({next,review})=>advanceRuntimeContract({database:db,previousPolicy:policy,nextPolicy:next,review});
 return {db,directory,column,policy,state,current,beforeRows,beforeBudget,proposal,advance,async close(){db.close();await rm(directory,{recursive:true,force:true});}};
