test('authorized cumulative request/input chain preserves rows and history, and activates each genuine new iteration exactly once',async()=>{
 const f=await fixture();try{
  const proposal=await f.proposal();assert(isRuntimePolicy(proposal.next));f.advance(proposal);const after=JSON.parse(f.current());
  assert.deepEqual(f.db.prepare('SELECT * FROM evaluation_reservations ORDER BY rowid').all(),f.beforeRows);assert.deepEqual({...f.db.prepare('SELECT * FROM evaluation_budgets').get(),[f.column]:null},{...f.beforeBudget,[f.column]:null});
  for(const key of ['startedAtMs','deadlineAtMs','lastNow','windows','dispatches','admissions','benchmarkIterationHistory','predecessorReservations','predecessorBudget'])assert.deepEqual(after[key],JSON.parse(JSON.stringify(f.state[key])));
  assert.equal(after.halted,null);assert.equal(after.cancelled,false);assert.equal(after.benchmarkIterationActivatedAtMs,undefined);assert.equal(after.contractHistory.length,1);assert.equal(after.contractHistory[0].halted,'EvaluationBudgetExceeded');assert.equal(after.contractHistory[0].cancelled,true);assert.deepEqual(after.contractHistory[0].policy,f.policy);
  const control=createRuntimeControl({database:f.db,policy:proposal.next,now:()=>8000000});control.activate();const active=JSON.parse(f.current());assert.equal(active.deadlineAtMs,15200000);assert.equal(active.benchmarkIterationHistory.length,2);assert.equal(active.startedAtMs,1000);assert.equal(active.windows.length,2);
  createRuntimeControl({database:f.db,policy:proposal.next,now:()=>8001000}).activate();const resumed=JSON.parse(f.current());assert.equal(resumed.deadlineAtMs,15200000);assert.equal(resumed.benchmarkIterationActivatedAtMs,8000000);assert.equal(resumed.benchmarkIterationHistory.length,2);assert.equal(resumed.windows.length,2);
  const ledger=createEvaluationLedger({database:f.db,budgetId:f.policy.budgetId,policy:original,runtimePolicy:proposal.next,now:()=>8002000,logger:()=>{},accountingMode:'estimated',ownerDecision:decision});assert.equal(ledger.snapshot().value.requests,2000);assert.equal(ledger.snapshot().value.unresolvedRequests,24);assert.equal(ledger.snapshot().value.costNanodollars,2500000000);
  assert.equal(ledger.reserve({key:'synthetic-after-raise',inputTokens:15997999,outputTokens:1,costNanodollars:1,model:'synthetic/model'}).ok,true);
  assert.deepEqual(ledger.reserve({key:'synthetic-over-input',inputTokens:2,outputTokens:1,costNanodollars:1,model:'synthetic/model'}),{ok:false,error:{kind:'EvaluationBudgetExceeded',field:'inputTokens'}});
  assert.equal(proposal.next.maximumCostNanodollars,8000000000);assert.equal(proposal.next.maximumAdditionalRecoveries,null);assert.equal(original.maximumOutputTokens,3000000);assert.equal(JSON.parse(f.db.prepare('SELECT policy FROM evaluation_budgets').get().policy).maximumCostNanodollars,1000000000);
  assert.throws(()=>f.advance(proposal),/EvaluationRuntimePolicyConflict/,'same extension cannot be reapplied against its old state');
 }finally{await f.close();}
});
for(const [name,approvalChange] of Object.entries({missingOwner:{ownerAuthorized:false},wrongAnswer:{ownerAnswer:'Unrelated permission'},wrongPreviousRequests:{previousMaximumRequests:1200},wrongRequests:{maximumRequests:5000},wrongInput:{maximumInputTokens:32000000},wrongPreviousInput:{previousMaximumInputTokens:3000000},wrongOutput:{maximumOutputTokens:6000000},wrongCap:{cumulativeCapNanodollars:9000000000},counterReset:{resetCounters:true},startReset:{resetOriginalStart:true},reserveDiscard:{retainAllUnknownReserves:false}}))test(`quota raise rejects ${name} atomically`,async()=>{const f=await fixture();try{const before=f.current(),p=await f.proposal({approvalChange});assert.throws(()=>f.advance(p),/EvaluationRequestExtensionConflict|EvaluationInputExtensionConflict/);assert.equal(f.current(),before);assert.deepEqual(f.db.prepare('SELECT * FROM evaluation_reservations ORDER BY rowid').all(),f.beforeRows);}finally{await f.close();}});
for(const [name,closureChange] of Object.entries({wrongReason:{stopReason:'IntegrationSupervisorSignal'},cleanupMissing:{cleanupConfirmed:false},processMissing:{ownedPid:null},successfulExit:{code:0},signaled:{signal:'SIGTERM'},priorRun:{finishedAt:new Date(999).toISOString()},failure:{failure:'fake'},monitorFailure:{monitorFailure:'fake'}}))test(`budget cancellation rejects ${name} closure atomically`,async()=>{const f=await fixture();try{const before=f.current(),p=await f.proposal({closureChange});assert.throws(()=>f.advance(p),/EvaluationStoppedTransportConflict/);assert.equal(f.current(),before);}finally{await f.close();}});
for(const [name,proofChange] of Object.entries({missingAuthority:{ownerAuthorized:false},wrongQuote:{ownerAnswer:'resume'},wrongState:{previousRuntimeSha256:other},wrongClosureHash:{closureSha256:other},discardReserves:{retainAllUnknownReserves:false},counterReset:{resetCounters:true},fakeUnknown:{unknownReservations:[{key:'fake',cost:1,uncertainty_version:1}]}}))test(`budget cancellation rejects ${name} proof atomically`,async()=>{const f=await fixture();try{const before=f.current(),p=await f.proposal({proofChange});assert.throws(()=>f.advance(p),/EvaluationStoppedTransportConflict/);assert.equal(f.current(),before);}finally{await f.close();}});
test('no proof, outstanding call, wrong saturation, stale source, arbitrary ceilings and legacy-source replay cannot expand authority',async()=>{
 const f=await fixture();try{
  let p=await f.proposal();const noProof={...p.review};delete noProof.stoppedTransport;assert.throws(()=>f.advance({...p,review:noProof}),/EvaluationRequestExtensionConflict/);
  p.next.requestExtension.sourceSha256=other;assert.throws(()=>f.advance(p),/EvaluationRequestExtensionConflict/);
  p=await f.proposal();p.next.requestExtension.previousRuntimeSha256=other;assert.throws(()=>f.advance(p),/EvaluationRequestExtensionConflict/);
  p=await f.proposal({approvalChange:{ownerAnswer:'Raise benchmark requests to 2,000'}});assert.throws(()=>f.advance(p),/EvaluationRequestExtensionConflict/);
  assert.equal(isRuntimePolicy({...p.next,requestExtension:{...p.next.requestExtension,maximumRequests:5000}}),false);assert(isRuntimePolicy(f.policy));
  f.db.prepare('UPDATE evaluation_reservations SET response=NULL WHERE key=?').run('synthetic-paid-1999');p=await f.proposal();assert.throws(()=>f.advance(p),/EvaluationStoppedTransportConflict/);f.db.prepare('UPDATE evaluation_reservations SET response=? WHERE key=?').run('{}','synthetic-paid-1999');
  f.db.prepare('DELETE FROM evaluation_reservations WHERE key=?').run('synthetic-paid-1999');p=await f.proposal();assert.throws(()=>f.advance(p),/EvaluationStoppedTransportConflict/);
 }finally{await f.close();}
});
