test('a genuine new iteration gets its own first window before the old window expires; same ID keeps it',async()=>{
 const f=await fixture();try{
  const before={...f.state,halted:null,cancelled:false};f.db.prepare('UPDATE evaluation_budgets SET '+f.column+'=?').run(JSON.stringify(before));
  const timerSource=join(f.directory,'early-new-iteration-clock.json'),timerText=JSON.stringify({ownerAuthorized:true,ownerAnswer:'automatically reset it to 2 hours for each new benchmark run',durationMilliseconds:7200000,cumulativeCapNanodollars:8000000000,resetCounters:false,resetOriginalStart:false,retainAllUnknownReserves:true});await writeFile(timerSource,timerText);
  const next={...structuredClone(f.policy),source:'synthetic-repaired-code',benchmarkIteration:{source:timerSource,sourceSha256:sha(timerText),previousRuntimeSha256:sha(f.current()),previousDeadlineAtMs:before.deadlineAtMs,previousWindowCount:before.windows.length,iterationId:'synthetic-early-new-run',durationMilliseconds:7200000}};
  advanceRuntimeContract({database:f.db,previousPolicy:f.policy,nextPolicy:next,review:{verdict:'PASS',BLOCKING:'NONE',codeSha256:next.codeSha256,modelsSha256:next.modelsSha256,gateSha256:h}});
  const pending=JSON.parse(f.current());assert.deepEqual(pending.windows,before.windows);assert.equal(pending.benchmarkIterationActivatedAtMs,undefined);
  const control=createRuntimeControl({database:f.db,policy:next,now:()=>2000}),window=control.activate();assert.deepEqual(window,{startedAtMs:2000,deadlineAtMs:1802000});
  const active=JSON.parse(f.current());assert.deepEqual(active.windows.slice(0,-1),before.windows);assert.equal(active.windows.length,2);assert.equal(active.deadlineAtMs,7202000);assert.equal(active.benchmarkIterationHistory.length,2);assert.equal(active.startedAtMs,before.startedAtMs);
  const budget=f.db.prepare('SELECT * FROM evaluation_budgets').get();assert.deepEqual({...budget,[f.column]:null},{...f.beforeBudget,[f.column]:null});assert.deepEqual(f.db.prepare('SELECT * FROM evaluation_reservations ORDER BY rowid').all(),f.beforeRows);
  assert.deepEqual(active.dispatches,before.dispatches);assert.deepEqual(active.admissions,before.admissions);
  assert.deepEqual(createRuntimeControl({database:f.db,policy:next,now:()=>3000}).activate(),window);const resumed=JSON.parse(f.current());assert.equal(resumed.windows.length,2);assert.equal(resumed.deadlineAtMs,7202000);assert.equal(resumed.benchmarkIterationHistory.length,2);
  for(const corrupt of ['wrong-start','missing-history','wrong-history-source']){const bad=structuredClone(resumed);if(corrupt==='wrong-start')bad.windows.at(-1).startedAtMs=1500;if(corrupt==='missing-history')bad.benchmarkIterationHistory.pop();if(corrupt==='wrong-history-source')bad.benchmarkIterationHistory.at(-1).sourceSha256=other;f.db.prepare('UPDATE evaluation_budgets SET '+f.column+'=?').run(JSON.stringify(bad));assert.throws(()=>createRuntimeControl({database:f.db,policy:next,now:()=>4000}),/EvaluationRuntimeStateInvalid/);f.db.prepare('UPDATE evaluation_budgets SET '+f.column+'=?').run(JSON.stringify(resumed));}
  for(const now of [1802000,3602000,5402000])createRuntimeControl({database:f.db,policy:next,now:()=>now}).activate();const final=JSON.parse(f.current());assert.equal(final.windows.length,5);assert.equal(final.windows.at(-1).deadlineAtMs,7202000);
  assert.throws(()=>createRuntimeControl({database:f.db,policy:next,now:()=>7202000}).activate(),/EvaluationDeadlineExceeded/);assert.equal(JSON.parse(f.current()).windows.length,5);
  const third={...next,benchmarkIteration:{...next.benchmarkIteration,previousRuntimeSha256:sha(f.current()),previousDeadlineAtMs:final.deadlineAtMs,previousWindowCount:final.windows.length,iterationId:'synthetic-third-run'}};advanceRuntimeContract({database:f.db,previousPolicy:next,nextPolicy:third,review:{verdict:'PASS',BLOCKING:'NONE',codeSha256:third.codeSha256,modelsSha256:third.modelsSha256,gateSha256:h}});const thirdWindow=createRuntimeControl({database:f.db,policy:third,now:()=>5403000}).activate();assert.equal(thirdWindow.startedAtMs,5403000);assert.equal(JSON.parse(f.current()).benchmarkIterationHistory.length,3);assert.equal(JSON.parse(f.current()).windows.length,6);
 }finally{await f.close();}
});

