  const owner=JSON.stringify({ownerAuthorized:true,benchmarkOnly:true,ownerAnswer:externalOwnerAnswer,...ownerChange}),ownerSource=join(f.directory,'external-owner.json');await writeFile(ownerSource,owner);
  const unknown=f.db.prepare('SELECT key,cost,uncertainty_version FROM evaluation_reservations WHERE key=?').all(key),proof=JSON.stringify({ownerAuthorized:true,benchmarkOnly:true,classification:'external-transport',ownerSource,ownerSha256:sha(owner),cumulativeCapNanodollars:8000000000,previousRuntimeSha256,closureSource,closureSha256:sha(closure),unknownReservations:unknown,resumeCancellation:true,resetCounters:false,resetOriginalStart:false,retainAllUnknownReserves:true,...proofChange}),source=join(f.directory,'external-proof.json');await writeFile(source,proof);
